s+='''
fn variant() -> String {
    std::env::var("MK_VARIANT").unwrap_or_default()
}

fn proto_path_prior(block: &CodeBlock) -> f64 {
    let v = variant();
    if !v.contains("path") {
        return 1.0;
    }
    let demo = ["examples", "example", "benches", "bench", "scripts", "demo", "demos"];
    let demo_app = v.contains("app");
    let mut comps: Vec<&str> = block.file.as_str().split('/').collect();
    comps.pop();
    if comps.iter().any(|c| demo.contains(c) || (demo_app && *c == "app")) { 0.6 } else { 1.0 }
}

fn prefix_eq(a: &str, b: &str) -> bool {
    a == b || (a.len() >= 3 && b.len() >= 3 && (a.starts_with(b) || b.starts_with(a)))
}

fn proto_name_boost(block: &CodeBlock, q: &[&str]) -> f64 {
    let v = variant();
    if q.is_empty() {
        return 1.0;
    }
    let nt = block.name.as_deref().map(crate::tokens::tokenize_source).unwrap_or_default();
    if nt.is_empty() {
        return 1.0;
    }
    let m = if v.contains("stem") {
        q.iter().filter(|t| nt.iter().any(|n| prefix_eq(n, t))).count()
    } else {
        q.iter().filter(|t| nt.iter().any(|n| n == *t)).count()
    } as f64;
    let (ql, nl) = (q.len() as f64, nt.len() as f64);
    if v.contains("dice") {
        round6(1.0 + 2.0 * 2.0 * m / (ql + nl))
    } else if v.contains("full") {
        round6(1.0 + 2.0 * m / ql + if m >= ql { 2.0 } else { 0.0 })
    } else {
        round6(1.0 + 2.0 * m / ql)
    }
}
